<?php
requireAdmin();
$audiences=['all'=>'כל הפעילות','member'=>uiMessage('admin.release.05'),'demo'=>uiMessage('admin.release.06'),'admin'=>'מנהל','qa'=>'בדיקות מסומנות','unclassified'=>'לא מסווג'];
$audience=(string)($_GET['audience']??'all');if(!isset($audiences[$audience]))$audience='all';
$classified="SELECT e.*,COALESCE(a.audience,f.audience,CASE WHEN e.member IS NOT NULL AND e.member<>'' THEN 'member' ELSE 'unclassified' END) audience FROM network_events e LEFT JOIN network_event_audience a ON a.event_id=e.id LEFT JOIN network_member_flags f ON f.member=e.member LEFT JOIN member_profiles p ON p.member=e.member WHERE e.created>?";
$metrics=socialQuery("SELECT event,language,audience,COUNT(*) total,COUNT(DISTINCT member) accounts FROM ($classified) WHERE (?='all' OR audience=?) GROUP BY event,language,audience ORDER BY event,audience",[time()-604800,$audience,$audience])->fetchAll();
?><section id="product-metrics"><h2>פעולות מוצר ב־7 הימים האחרונים</h2><p><?=e(uiMessage('admin.release.07'))?></p><form method="get"><input type="hidden" name="view" value="history"><label>קהל<select name="audience"><?php foreach($audiences as $key=>$label):?><option value="<?=$key?>" <?=$audience===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><button>הצגת סיכום</button></form><table><thead><tr><th>פעולה</th><th>שפה</th><th>קהל</th><th>אירועים</th><th>חשבונות מזוהים</th></tr></thead><tbody><?php foreach($metrics as $metric):?><tr><td><?=e($metric['event'])?></td><td><?=e($metric['language'])?></td><td><?=e($audiences[$metric['audience']]??'לא מסווג')?></td><td><?=(int)$metric['total']?></td><td><?=(int)$metric['accounts']?></td></tr><?php endforeach?></tbody></table><?php if(!$metrics):?><p role="status">אין אירועים בחיתוך שנבחר.</p><?php endif?><p><?=e(uiMessage('admin.metrics.checked',['time'=>gmdate('Y-m-d H:i:s')]))?></p></section>
